const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and date
  const point = ee.Geometry.Point([40.190004, -122.555169]);
  const date = '2020-08-25';
  const startDate = '2020-08-24';
  const endDate = '2020-08-26';

  // 2. Load MERRA-2 black carbon data
  // MERRA-2 BC is in kg/m3, need to convert to mg/m3 (multiply by 1e6)
  const merra2BC = ee.ImageCollection('MERRA2/400/inst3_3d_aer_Nv')
    .filterDate(startDate, endDate)
    .select('BC');

  // Check collection size
  const collectionSize = merra2BC.size().getInfo();
  console.log(`MERRA-2 BC Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No MERRA-2 data available for this date.');
    console.log('C1');
    return;
  }

  // 3. Get the closest image to the date
  const bcImage = merra2BC.first();

  // 4. Extract black carbon value at the point (convert kg/m3 to mg/m3)
  const bcValue = bcImage.sample(point, 50000).first().get('BC').getInfo();

  // Convert kg/m³ to mg/m³
  const bcMgM3 = bcValue * 1e6;

  console.log(`Date: ${date}`);
  console.log(`Location: 40.190004, -122.555169`);
  console.log(`Black Carbon (raw kg/m³): ${bcValue}`);
  console.log(`Black Carbon (mg/m³): ${bcMgM3.toFixed(4)}`);

  // 5. Validation and comparison
  if (bcValue === null || isNaN(bcValue) || bcValue < 0) {
    console.log('C3');
    return;
  }

  // 6. Compare to threshold of 12 mg/m³
  if (bcMgM3 > 12) {
    console.log(`Result: ${bcMgM3.toFixed(4)} mg/m³ > 12 mg/m³ threshold`);
    console.log('A');
  } else {
    console.log(`Result: ${bcMgM3.toFixed(4)} mg/m³ ≤ 12 mg/m³ threshold`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
